// ---------- Static Data (Miners, Items, Daily Tasks, Achievements) ----------
async function seedStaticData() {
  const minersRef = db.ref('miners');
  const snapshot = await minersRef.once('value');
  if (!snapshot.exists()) {
    const miners = {
      miner1: { id: 'miner1', name: 'Mehmet Dayı', cost: 10000, hourlyKMR: 100, multiplier: 2 },
      miner2: { id: 'miner2', name: 'Şemsi Dayı', cost: 20000, hourlyKMR: 250, multiplier: 4 },
