      miner4: { id: 'miner4', name: 'Beyza Nene', cost: 100000, hourlyKMR: 2000, multiplier: 8 },
      miner5: { id: 'miner5', name: 'Ali Usta', cost: 250000, hourlyKMR: 5000, multiplier: 10 }
    };
    await minersRef.set(miners);
  }

  const itemsRef = db.ref('items');
  const itemsSnap = await itemsRef.once('value');
  if (!itemsSnap.exists()) {
    const items = {};
    const rarities = ['Common', 'Rare', 'Epic', 'Legendary', 'Mythic'];
    for (let i = 1; i <= 100; i++) {
