      items[`item${i}`] = { id: `item${i}`, name: `${rarity} Eşya ${i}`, rarity, ph };
    }
    await itemsRef.set(items);
  }

  const dailyRef = db.ref('dailyRewards');
  const dailySnap = await dailyRef.once('value');
  if (!dailySnap.exists()) {
    const tasks = {
