// Helper: update totalPH for a user
async function updateTotalPH(uid) {
  const userSnap = await db.ref(`users/${uid}`).once('value');
  const user = userSnap.val();
  if (!user) return;
  const miner = (await db.ref(`miners/${user.activeMinerId}`).once('value')).val();
  if (!miner) return;
  let itemsPH = 0;
  for (const item of user.items || []) {
    const itemData = (await db.ref(`items/${item.id}`).once('value')).val();
    if (itemData) itemsPH += itemData.ph;
  }
  const totalPH = itemsPH * miner.multiplier;
  await db.ref(`users/${uid}/totalPH`).set(totalPH);
  await db.ref(`leaderboard/${uid}`).set({ uid, username: user.username, totalPH });
}

// Offline earnings
exports.claimOfflineEarnings = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', 'Giriş gerekli');
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  if (!user) throw new functions.https.HttpsError('not-found', 'Kullanıcı bulunamadı');
  const lastLogin = user.lastLogin ? new Date(user.lastLogin) : new Date();
  const now = new Date();
  const diffHours = Math.min(8, (now - lastLogin) / (1000 * 3600));
  if (diffHours <= 0) return { message: 'Yeni kazanç yok' };
  const miner = (await db.ref(`miners/${user.activeMinerId}`).once('value')).val();
  const earnedKMR = Math.floor(diffHours * miner.hourlyKMR);
  await userRef.child('kmr').transaction(current => (current || 0) + earnedKMR);
  await userRef.child('lastLogin').set(admin.database.ServerValue.TIMESTAMP);
  return { message: `${earnedKMR} KMR kazandınız!` };
});

// Buy miner
exports.buyMiner = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', '');
  const { minerId } = data;
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  const minerSnap = await db.ref(`miners/${minerId}`).once('value');
  const miner = minerSnap.val();
  if (!miner) throw new functions.https.HttpsError('not-found', 'Madenci yok');
  if (user.banknot < miner.cost) throw new functions.https.HttpsError('failed-precondition', 'Yeterli banknot yok');
  await userRef.child('banknot').transaction(current => current - miner.cost);
  await userRef.child('activeMinerId').set(minerId);
  await updateTotalPH(uid);
  return { message: `${miner.name} satın alındı!` };
});

// Currency conversion
exports.convertCurrency = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', '');
  const { from, to, amount } = data;
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  let rate = 1;
  if (from === 'kmr' && to === 'banknot') rate = 1000;
  else if (from === 'banknot' && to === 'kmr') rate = 0.001;
  else if (from === 'banknot' && to === 'cekip') rate = 10000;
  else if (from === 'cekip' && to === 'banknot') rate = 10000;
  else throw new functions.https.HttpsError('invalid-argument', 'Geçersiz dönüşüm');
  const required = amount;
  let available;
  if (from === 'kmr') available = user.kmr;
  else if (from === 'banknot') available = user.banknot;
  else available = user.kasa;
  if (available < required) throw new functions.https.HttpsError('failed-precondition', 'Yetersiz bakiye');
  const result = Math.floor(required / rate);
  await userRef.child(from).transaction(current => current - required);
  await userRef.child(to).transaction(current => (current || 0) + result);
  return { message: `${required} ${from} → ${result} ${to} dönüştürüldü` };
});

// Open box
exports.openBox = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', '');
  const { boxType } = data;
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  let cost;
  switch (boxType) {
    case 'small': cost = 1000; break;
    case 'medium': cost = 5000; break;
    case 'large': cost = 25000; break;
    case 'legendary': cost = 100000; break;
    default: throw new functions.https.HttpsError('invalid-argument', 'Geçersiz kutu');
  }
  if (user.kmr < cost) throw new functions.https.HttpsError('failed-precondition', 'Yetersiz KMR');
  await userRef.child('kmr').transaction(current => current - cost);
  const r = Math.random();
  let message = '';
  if (r < 0.6) {
    const gain = Math.floor(Math.random() * 500) + 100;
    await userRef.child('kmr').transaction(current => (current || 0) + gain);
    message = `${gain} KMR kazandınız!`;
  } else if (r < 0.9) {
    const gain = Math.floor(Math.random() * 10) + 1;
    await userRef.child('banknot').transaction(current => (current || 0) + gain);
    message = `${gain} banknot kazandınız!`;
  } else {
    const itemsSnap = await db.ref('items').once('value');
    const items = itemsSnap.val();
    const itemIds = Object.keys(items);
    const randomItemId = itemIds[Math.floor(Math.random() * itemIds.length)];
    const item = items[randomItemId];
    await userRef.child('items').transaction(current => {
      current = current || [];
      current.push({ id: randomItemId, name: item.name, rarity: item.rarity, ph: item.ph });
      return current;
    });
    await updateTotalPH(uid);
    message = `${item.name} (${item.rarity}) eşyası kazandınız!`;
  }
  return { message };
});

// Spin wheel
exports.spinWheel = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', '');
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  const lastSpin = user.lastSpinDate ? new Date(user.lastSpinDate) : new Date(0);
  const now = new Date();
  if (lastSpin.toDateString() === now.toDateString()) {
    throw new functions.https.HttpsError('failed-precondition', 'Bugün zaten çevirdiniz');
  }
  const prizes = [100, 200, 500, 1000, 1, 5, 10, 'item'];
  const prize = prizes[Math.floor(Math.random() * prizes.length)];
  if (prize === 'item') {
    const itemsSnap = await db.ref('items').once('value');
    const items = itemsSnap.val();
    const itemIds = Object.keys(items);
    const randomItemId = itemIds[Math.floor(Math.random() * itemIds.length)];
    const item = items[randomItemId];
    await userRef.child('items').transaction(current => {
      current = current || [];
      current.push({ id: randomItemId, name: item.name, rarity: item.rarity, ph: item.ph });
      return current;
    });
    await updateTotalPH(uid);
    await userRef.child('lastSpinDate').set(now.toISOString());
    return { message: `Çark: ${item.name} kazandınız!` };
  } else if (prize >= 1 && prize <= 1000) {
    await userRef.child('kmr').transaction(current => (current || 0) + prize);
    await userRef.child('lastSpinDate').set(now.toISOString());
    return { message: `Çark: ${prize} KMR kazandınız!` };
  } else {
    await userRef.child('banknot').transaction(current => (current || 0) + prize);
    await userRef.child('lastSpinDate').set(now.toISOString());
    return { message: `Çark: ${prize} banknot kazandınız!` };
  }
});

