// Claim daily task
exports.claimDailyTask = functions.https.onCall(async (data, context) => {
  if (!context.auth) throw new functions.https.HttpsError('unauthenticated', '');
  const { taskId } = data;
  const uid = context.auth.uid;
  const userRef = db.ref(`users/${uid}`);
  const userSnap = await userRef.once('value');
  const user = userSnap.val();
  if (user.dailyTasksCompleted && user.dailyTasksCompleted[taskId]) {
    throw new functions.https.HttpsError('failed-precondition', 'Bu görev zaten tamamlandı');
  }
  const taskSnap = await db.ref(`dailyRewards/${taskId}`).once('value');
  const task = taskSnap.val();
  if (!task) throw new functions.https.HttpsError('not-found', 'Görev yok');
  await userRef.child('kmr').transaction(current => (current || 0) + task.reward);
  await userRef.child(`dailyTasksCompleted/${taskId}`).set(true);
  return { message: `${task.name} tamamlandı, ${task.reward} KMR kazandınız!` };
});

