// Scheduled league reward distribution (every 20 minutes)
exports.distributeLeagueRewards = functions.pubsub.schedule('every 20 minutes').onRun(async () => {
  const usersSnap = await db.ref('users').once('value');
  const users = usersSnap.val();
  const leagues = { çırak: [], amatör: [], usta: [] };
  for (const [uid, user] of Object.entries(users)) {
    const totalPH = user.totalPH || 0;
    let league;
    if (totalPH < 1000) league = 'çırak';
    else if (totalPH < 5000) league = 'amatör';
    else league = 'usta';
    leagues[league].push({ uid, totalPH, user });
  }
  const rewards = { çırak: 10, amatör: 100, usta: 500 };
  for (const [league, members] of Object.entries(leagues)) {
    if (members.length === 0) continue;
    const totalPH = members.reduce((sum, m) => sum + m.totalPH, 0);
    for (const member of members) {
      const share = (member.totalPH / totalPH) * rewards[league];
      const cekipReward = Math.floor(share);
      if (cekipReward > 0) {
        await db.ref(`users/${member.uid}/kasa`).transaction(current => (current || 0) + cekipReward);
      }
    }
  }
  return null;
});
